Loss.create!([
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "HB2 causes cancellation of Deutsche Bank's planned Cary expansion", slug: "deutsche-bank", description: "Deutsche Bank cancels jobs expansion in Cary, NC in response to HB2. The company had been planning to add 250 jobs, which will now go to Florida.", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 6% of the total losses to the state of North Carolina to date, the  loss of this company expansion is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"We take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\"\n<br><br>\n- John Cryan, Co-Chief Executive Officer of Deutsche Bank.\n <a class=\"link\" href=\"https://www.db.com/usa/content/en/3639.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Deutsche Bank expansion is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.bizjournals.com/triangle/news/2016/07/27/three-months-after-hb2-jobs-freeze-in-cary.html", "meta"=>{"publication"=>"Triangle Business Journal", "title"=>"After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", "date"=>"7/27/16", "author"=>"Lauren K. Ohnesorge", "accessed"=>"9/9/16"}}, {"link"=>"http://www.newsobserver.com/news/business/article71314817.html", "meta"=>{"publication"=>"The News and Observer", "title"=>"Economic impact of HB2 mushrooms in the Triangle", "date"=>"4/12/16", "author"=>"David Bracken and Paul A. Specht", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "Deutsche Bank", photo_credit: "", tweet: "Citing HB2, Deutsche Bank cancels it's planned NC expansion. Losses top $20 million - http://ow.ly/glr4304kcNE #RepealHB2 #StopHB2gether"},
  {date: "2016-04-26 04:00:00", amount: "1500000.0", title: "Due to HB2, W. K. Kellogg Foundation conference moved out of Asheville", slug: "w-k-kellogg", description: "The W. K. Kellogg Foundation moves it's conference out of Asheville over House Bill 2, resulting in an estimated $1.5 million loss for the area. The foundation released a public statement condemning the bill.", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $1,500,000 to the total of $350,873,000, the loss of this conference hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"It is very disappointing that North Carolina, among other states, has thought to enact legislation that overturns protections for all people including LGBT people, sanctioning open discrimination against them.\"\n<br><br>\n- W.K. Kellogg Foundation\n <a class=\"link\" href=\"https://www.wkkf.org/news-and-media/article/2016/04/statement-on-protection-of-human-rights-in-lgbt-communities-across-the-country\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.citizen-times.com/story/news/local/2016/04/25/hb2-costs-asheville-15m-conference/83513046/", "meta"=>{"publication"=>"Citizen Times", "title"=>"HB2 costs Asheville $1.5M conference", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"John Boyle"}}, {"link"=>"http://wlos.com/news/local/asheville-conference-estimated-to-have-15-million-impact-canceled-due-to-hb2", "meta"=>{"publication"=>"News 13 WLOS", "title"=>"Asheville conference estimated to have $1.5 million impact canceled due to HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Kimberly King and Krystyna Biassou"}}], active: true, featured: true, short_name: "W. K. Kellogg Foundation", photo_credit: "", tweet: "W. K. Kellogg Foundation conf is moved out of Asheville over #HB2, costing $1.5 M - http://ow.ly/D617304pfuV #RepealHB2 #StopHB2gether"},
  {date: "2016-05-20 04:00:00", amount: "1640000.0", title: "Citing HB2, Maroon 5 cancels NC shows", slug: "maroon-5", description: "Maroon 5 cancels shows in Raleigh and Charlotte over HB2. The band issued a statement that they feel that everyone should be treated equally.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $1,640,000 to the total of $350,873,000, the loss of this concert hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"We don’t want to penalize our fans in North Carolina by not performing for them, but in the end it comes down to what we feel is morally right as well feel everyone should be treated equally.\"\n<br><br>\n- Adam Levine\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Maroon 5 is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.wral.com/maroon-5-cancels-nc-shows-citing-hb2/15716462/", "meta"=>{"publication"=>"WRAL", "title"=>"Citing HB2, Maroon 5 cancels shows in Raleigh and Charlotte", "date"=>"5/20/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article78823022.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Maroon 5 cancels N.C. shows over HB2, calling decision ‘morally right", "date"=>"5/20/16", "accessed"=>"9/9/16", "author"=>"Theoden Janes"}}, {"link"=>"CUSTOM_CALC", "anchor"=>true}], active: true, featured: false, short_name: "Maroon 5", photo_credit: "FashionStock.com / Shutterstock.com", tweet: "Another voice in the fight against HB2, @maroon5 cancels NC shows to protest the bill - http://ow.ly/J7EK304pl53 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-18 04:00:00", amount: "1100000.0", title: "Boston cancels 3 North Carolina shows on their tour to raise awareness about HB2", slug: "boston", description: "The band Boston cancelled shows in Raleigh, Charlotte and Greensboro in protest over HB2. They issued a statement supporting human rights, and condemning the bill.", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nThe loss of $1,100,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"While the enjoyment of our fans is our central concern, and we have been looking forward to celebrating forty years of history performing for our listeners in North Carolina with spectacular live shows this spring, human rights are more important.\"\n<br><br>\n- Tom Scholzvia  Facebook\n <a class=\"link\" href=\"https://www.facebook.com/bandboston/posts/1176004065772990\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Boston in Raleigh, Charlotte, and and Greensboro is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.thetimesnews.com/news/20160418/boston-cancels-three-north-carolina-shows", "meta"=>{"publication"=>"Times News", "title"=>"Boston cancels three North Carolina shows", "date"=>"4/18/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.charlotteobserver.com/news/business/article72455377.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Boston cancels North Carolina shows because of LGBT law", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Katherine Peralta"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Boston", photo_credit: "", tweet: "Boston cancels 3 North Carolina shows to raise awareness over HB2 - http://ow.ly/FH8w304pllH #RepealHB2 #StopHB2gether"},
  {date: "2016-04-18 04:00:00", amount: "191000.0", title: "Record Store Day moved from Raleigh to Baltimore over HB2", slug: "record-store-day", description: "Record Store Day pulls out of NC to protest House Bill 2. The event would have brought an estimated $190,000 to the state.", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $191,000 to the total of $350,873,000, the loss of this event hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"We look forward to showing off Raleigh and the true spirit of North Carolina after the repeal of HB2.\n\n\"\n<br><br>\n- Carrie Colliton, Director of Marketing, Department of Record Stores, and co-founder of Record Store Day.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Record Store Day in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://www.dailykos.com/story/2016/4/19/1517370/-NC-s-HB2-The-Hits-Just-Keep-On-Rolling", "meta"=>{"publication"=>"Daily Kos", "title"=>"NC's HB2 - The Hits Just Keep On Rolling....", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Lamont Cranston"}}], active: true, featured: false, short_name: "Record Store Day", photo_credit: "DutchScenery / Shutterstock.com", tweet: "North Carolina loses $190,000 over the HB2 related loss of Record Store Day - http://ow.ly/r2Zb304piG5 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-06 04:00:00", amount: "1000.0", title: "Duck PD cancels spring conference due to HB2", slug: "duck-pd", description: "The police department of Duck, NC was planning to host a spring conference but had to cancel due to the number of travel bans to the state over HB2. At least 15 people were planning on attending from out of town.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nThe loss of $1,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://outerbanksvoice.com/2016/04/06/hb2-results-in-cancellation-of-duck-p-d-sponsored-conference/", "meta"=>{"publication"=>"Outer Banks Voice", "title"=>"HB2 results in cancellation of Duck P.D.-sponsored conference", "date"=>"4/6/16", "accessed"=>"9/10/16", "author"=>"Russ Lay"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Duck Police Department", photo_credit: "", tweet: "The Duck PD cancels their spring conference due to HB2 related travel bans - http://ow.ly/6rVT304plKR #RepealHB2 #StopHB2gether"},
  {date: "2016-07-13 04:00:00", amount: "1035000.0", title: "Duke vs. Albany Basketball game cancelled over HB2", slug: "duke-vs-albany-basketball", description: "New York governor Andrew Cuomo issues an executive order barring travel to NC, resulting in the cancellation of the Duke vs. Albany game. Cuomo is just one of dozens of public officials from states around the country banning travel to North Carolina in response to the discriminatory bill.", template: "\nNC loses even more money due to HB2.<br><br>\n\nThe loss of $1,035,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"The State University of New York supports Governor Cuomo's executive order banning all non-essential travel to the state of North Carolina.\"\n<br><br>\n- Holly Liapsis, SUNY spokesperson.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.si.com/college-basketball/2016/07/13/albany-duke-canceled-governor-andrew-cuomo-north-carolina-bathroom-law", "meta"=>{"publication"=>"Sports Illustrated", "title"=>"Albany game at Duke canceled over North Carolina HB2 law", "date"=>"7/13/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.dukechronicle.com/article/2016/07/house-bill-2-leads-to-holes-in-duke-mens-basketball-field-hockey-schedules", "meta"=>{"publication"=>"Duke Chronicle", "title"=>"House Bill 2 leads to holes in Duke men's basketball, field hockey schedules", "date"=>"7/14/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Duke vs. Albany", photo_credit: "Katherine Welles / Shutterstock.com", tweet: "Thank you, @NYGovCuomo for standing against HB2 and cancelling Albany's game at Duke - http://ow.ly/3JXI304klQK #RepealHB2 #StopHB2gether"},
  {date: "2016-09-13 04:00:00", amount: "300000.0", title: "U.S. Association of Collegiate Fencing Clubs moves 2017 championship out of Winston-Salem", slug: "us-association-of-collegiate-fencing-clubs", description: "Winston-Salem sees U.S. Association of Collegiate Fencing Club's 2017 championship moved due to HB2. The two day event would have had an economic impact of $300,000.", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing  $300,000 to the total of $350,873,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.hickoryrecord.com/news/ncaa-moving---championships-from-north-carolina-over-hb/article_b1e6c176-79b9-11e6-8382-0b1e9c7435ed.html", "meta"=>{"accessed"=>"9/16/16", "publication"=>"Hickory Record", "title"=>"NCAA moving 2016-17 championships from North Carolina over HB2, civil rights protections", "author"=>"Jeff Mills", "date"=>"9/13/16"}}, {"link"=>"http://www.journalnow.com/news/local/forsyth-county-could-feel-ncaa-championship-ripple-effect-in-long/article_74762b70-ce7e-5492-8756-b6c807a8e30d.html", "meta"=>{"accessed"=>"9/16/16", "date"=>"9/13/16", "publication"=>"Winston-Salem Journal", "author"=>"Richard Craver", "title"=>"Forsyth County could feel NCAA championship ripple effect in long term"}}], active: true, featured: false, short_name: "U.S. Association of Collegiate Fencing Clubs", photo_credit: "", tweet: "US Assoc. of Collegiate Fencing Clubs cancels championship over HB2; loss of $300K for NC http://ow.ly/gwBc304kkAu #RepealHB2 #StopHB2gether"},
  {date: "2016-05-26 04:00:00", amount: "693000.0", title: "Citizen Science Association moves it's 2017 convention out of Raleigh over HB2", slug: "csa", description: "An increasing number of travel bans to the state over HB2 forced conference officials to move the CSA 2017 event out of Raleigh. Local officials estimate the move to cost $693,000 to the area.", template: "\nNC loses even more money due to HB2.<br><br>\n\nThe loss of $693,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"Our decision was based on our firm belief that our conferences ought to be held in locations and in ways that welcome all people into a safe space to discuss and advance the field of citizen science. \"\n<br><br>\n- Greg Newman, CSA Board Chair.\n <a class=\"link\" href=\"http://citizenscience.org/2016/05/26/in-support-of-our-core-values-a-conference-decision/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/13/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://citizenscience.org/2016/05/06/seeking-community-input-regarding-a-conference-conundrum/", "meta"=>{"accessed"=>"9/13/16", "publication"=>"Citizen Science", "title"=>"Seeking Community Input Regarding a Conference Conundrum", "date"=>"5/06/16"}}], active: true, featured: false, short_name: "Citizen Science Association", photo_credit: "", tweet: "Citizen Science Association moves 2017 conf from Raleigh costing the area $693,000 - http://ow.ly/rWNc304pdpP #RepealHB2 #StopHB2gether"},
  {date: "2016-04-21 04:00:00", amount: "183000.0", title: "The National Organization for Victim Assistance cancels a training event in Charlotte in opposition to HB2", slug: "nova", description: "The National Organization for Victim Assistance conference scheduled for August has been cancelled due to HB2. Over 1,000 people were planning to attend this event.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nThe loss of $183,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\n<br><br>\n- \n</blockquote>\n\nThe loss of the National Organization for Victim Assistance is not only a loss for Charlotte, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.charlotteobserver.com/news/business/article73023232.html", "meta"=>{"accessed"=>"9/14/16", "publication"=>"Charlotte Observer", "title"=>"Victim assistance organization cancels Charlotte event because of LGBT law", "date"=>"4/21/16", "author"=>"Katherine Peralta"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "National Organization for Victim Assistance", photo_credit: "", tweet: ".@NOVAVictims stands up to discriminatory HB2, cancelling Charlotte event - http://ow.ly/cuvj304phDb #RepealHB2 #StopHB2gether"},
  {date: "2016-05-17 04:00:00", amount: "230000.0", title: "NCLR Cancels moves it's 2016 conference from Raleigh to Miami in protest over HB2", slug: "nclr", description: "The National Council of La Raza moves their 2016 event out of Raleigh to protest House Bill 2. The group issued a statement in support of civil rights and LGBT groups in the state.", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $230,000 to the total of $350,873,000, the loss of this conference is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"By taking this action, we extend our support to the efforts of so many in North Carolina and the LGBT, civil rights and business communities to repeal this egregious law.\"\n<br><br>\n- Janet Murguía, NCLR President and CEO.\n <a class=\"link\" href=\"http://www.nclr.org/about-us/media/press/releases/NCLR-Press-Statement-NC-LGBT-051716\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.glaad.org/blog/nations-largest-latino-organization-cancels-nc-event-protest-anti-lgbt-law", "meta"=>{"accessed"=>"9/14/16", "publication"=>"GLAAD", "title"=>"Nation's largest Latino organization cancels NC event to protest anti-LGBT law", "date"=>"5/17/16", "author"=>"Richard Allen"}}], active: true, featured: false, short_name: "National Council of La Raza", photo_credit: "", tweet: ".@NCLR moves 2016 conference from Raleigh to Miami to protest HB2 - http://ow.ly/WOLS304peYi #RepealHB2 #StopHB2gether"},
  {date: "2016-04-06 04:00:00", amount: "208000.0", title: "Oregon based Johnstone supply cancels Raleigh meeting over HB2", slug: "johnstone-supply", description: "\nJohnstone supply cancels their 2018 fall meeting over HB2. The group stated that it's not in their best interest to hold it in a state that's not inclusive.", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nThe loss of $208,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"We just felt that it’s not in the best interest of our membership to go someplace that’s not inclusive.\"\n<br><br>\n- Janet Tipton, Director of Communications, Johnstone Supply.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.newsobserver.com/news/business/article71223992.html", "meta"=>{"accessed"=>"9/14/16", "author"=>"Paul A. Specht", "date"=>"4/11/16", "publication"=>"News and Observer", "title"=>"Raleigh visitors bureau says HB2 is affecting Wake economy"}}], active: true, featured: false, short_name: "Johnstone Supply", photo_credit: "", tweet: "Johnstone supply pulls conference from NC over HB2, resulting in at least $208,000 lost - http://ow.ly/82lU304pm4W#RepealHB2 #StopHB2gether"},
  {date: "2016-04-18 04:00:00", amount: "1700000.0", title: "Community Transporation Association of America pulls out of NC over HB2", slug: "ctaa", description: "The Community Transporation Association of America pulled their event from NC in protest over HB2. The organization was planning to bring over 1,000 people to NC, and will now be hosting it's event in Baltimore.", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nThe loss of $1,700,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"It's very significant. They were using five of our hotels, and it was a four day convention, so not only are the hotels being impacted, but restaurants, retail establishments, transportation companies. Everyone is going to feel the heat on this.\"\n<br><br>\n- Denny Edwards, CEO, Greater Raleigh Conventions and Visitor's Bureau.\n <a class=\"link\" href=\"http://abc11.com/news/raleigh-business-owner-fears-hb2-shutting-out-customers/1297766/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://associationsnow.com/2016/04/hb2-costing-north-carolina-business-convention-bureaus-warn/", "meta"=>{"publication"=>"Associations Now", "title"=>"HB2 costing North Carolina business, convention bureaus warn", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Ernie Smith"}}], active: true, featured: true, short_name: "Community Transportation Association of America", photo_credit: "", tweet: "North Carolina loses a whopping $1.7 million after CTAA pulls out over HB2 - http://ow.ly/PNCD304piiQ #RepealHB2 #StopHB2gether"},
  {date: "2016-04-18 04:00:00", amount: "706000.0", title: "Pearl Jam cancels show, citing HB2", slug: "pearl-jam", description: "Pearl Jam cancels it's planned show at Raleigh's Red Hat Ampitheater in opposition to HB2. The band released a statement calling the bill a 'despicable piece of legislation'.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nThe loss of $706,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"The HB2 law that was recently passed is a despicable piece of legislation that encourages discrimination against an entire group of American citizens. The practical implications are expansive and its negative impact upon basic human rights is profound.\"\n<br><br>\n- Pearl Jam\n <a class=\"link\" href=\"https://pearljam.com/news/north-carolina-concert-cancelled\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Pearl Jam in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/pearl-jam-cancel-raleigh-concert-to-oppose-bathroom-bill-20160418", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Pearl Jame cancel Raleigh concert to oppose 'Bathroom Bill'", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.bbc.com/news/world-us-canada-36079415", "meta"=>{"publication"=>"BBC", "title"=>"Pearl Jam cancel North Carolina concert over HB2 law", "date"=>"4/19/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: true, short_name: "Pearl Jam", photo_credit: "Matteo Chinellato / Shutterstock.com", tweet: "Pearl Jam cancels it's Raleigh show in opposition to HB2, the so-called 'bathroom bill' http://ow.ly/c2Qa304pjc8 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-18 04:00:00", amount: "54000.0", title: "ALSC cancels it's 2016 National Institute in Charlotte in protest of HB2", slug: "alsc", description: "The Association for Library Service to Children cancelled it's scheduled conference in Charlotte, joining the growing collection of organizations rallying against HB2. The ALSC has released a statement saying that HB2 is against their core values.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nThe loss of $54,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"The law contradicts the core values, purpose, and diversity work of ALSC and undermines civil rights and the fundamental principles upon which libraries are founded.\"\n<br><br>\n- ALSC\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.charlotteobserver.com/news/business/article72635277.html", "meta"=>{"accessed"=>"9/16/16", "publication"=>"Charlotte Observer", "title"=>"Library group cancels 2016 meetings in Charlotte because of HB2", "author"=>"Katherine Peralta", "date"=>"4/19/16"}}, {"link"=>"https://americanlibrariesmagazine.org/blogs/the-scoop/alsc-board-votes-cancel-national-institute-charlotte/", "meta"=>{"accessed"=>"9/16/16", "date"=>"4/18/16", "publication"=>"American Libraries Magazine", "title"=>"ALSC Board Votes to Cancel National Institute in Charlotte"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Association for Library Service to Children ", photo_credit: "American Libraries Magazine", tweet: ".@alscblog stands up to discriminatory HB2, cancelling Charlotte event in protest - http://ow.ly/BNGY304phOw #RepealHB2 #StopHB2gether"},
  {date: "2016-04-22 04:00:00", amount: "57000.0", title: "Citing HB2 travel bans, IASIR moves fall conference to Vegas", slug: "iasir", description: "The International Association of Security & Investigative Regulators cancelled a fall conference over HB2. Raleigh officials estimate the losses at $57,000.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nThe loss of $57,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.tradeshowexecutive.com/archive/industry-news/north-carolina-lgbt-turmoil-continues-costs-state-group-business/", "meta"=>{"accessed"=>"9/14/16", "author"=>"Sandi Cain", "date"=>"4/22/16", "publication"=>"Trade Show Executive", "title"=>"North Carolina LGBT Turmoil Continues, Costs State Group Business"}}], active: true, featured: false, short_name: "International Association of Security & Investigative Regulators", photo_credit: "", tweet: "IASIR cancels Raleigh event over HB2, with economic impact of $57,000 to the city - http://ow.ly/524U304phqc #RepealHB2 #StopHB2gether"},
  {date: "2016-09-12 04:00:00", amount: "51000000.0", title: "NCAA relocates 2016-17 championships out of NC in response to HB2", slug: "ncaa", description: "The NCAA relocates all of it's 2016-17 championships out of North Carolina in response to House Bill 2. The organization's public statement on the move cites a policy of fairness and inclusion.", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 15% of the total losses to the state of North Carolina to date, the  loss of this event is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"Fairness is about more than the opportunity to participate in college sports, or even compete for championships.\"\n<br><br>\n- Mark Emmert, President, NCAA.\n <a class=\"link\" href=\"http://www.ncaa.org/about/resources/media-center/news/ncaa-relocate-championships-north-carolina-2016-17\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.nytimes.com/2016/09/13/sports/ncaa-moves-championship-events-from-north-carolina.html?_r=0", "meta"=>{"accessed"=>"9/17/16", "author"=>"Marc Tracy and Alan Blinder", "date"=>"9/12/16", "publication"=>"New York Times", "title"=>"N.C.A.A. Moves Championship Events From North Carolina, Citing Anti-Gay-Rights Law"}}, {"link"=>"https://www.wired.com/2016/09/guess-much-anti-lgbtq-law-costing-north-carolina/", "meta"=>{"accessed"=>"9/18/16", "author"=>"Emma Gray Ellis", "date"=>"9/18/16", "publication"=>"Wired", "title"=>"Guess How Much That Anti-LGBTQ Law Is Costing North Carolina"}}, {"link"=>"http://edition.cnn.com/2016/09/12/sport/ncaa-pulls-championships-north-carolina-lgbtq/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Steve Visser", "date"=>"9/13/16", "publication"=>"CNN", "title"=>"NCAA pulls championships from North Carolina over LGBT law"}}], active: true, featured: true, short_name: "National Collegiate Athletic Association", photo_credit: "Al Sermeno Photography / Shutterstock.com", tweet: "The @ncaa pulls all championship games out of North Carolina in response to HB2 - http://ow.ly/OQah304klxR #RepealHB2 #StopHB2gether"},
  {date: "2016-05-27 04:00:00", amount: "62500000.0", title: "Attendance decreased at NC's Highpoint Market in response to HB2", slug: "highpoint-market", description: "The famed High Point market sees a drop in attendance related to HB2. Officals with the market state that they expect hundreds if not thousands of customers to boycott the event over the controversial new law.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $62,500,000 to the total of $350,873,000, the loss of this tradeshow hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"We obviously were concerned and we expressed that in the statement about House Bill 2. We did some cancelations.\"\n<br><br>\n- Tom Conley,  CEO of the High Point Market Authority.\n <a class=\"link\" href=\"http://www.homeaccentstoday.com/article/529919-high-point-market-authority-warns-house-bill-2-could-hurt-attendance\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.bizjournals.com/triad/news/2016/05/27/high-point-market-attendance-figures-released.html", "meta"=>{"publication"=>"Triad Business Journal", "title"=>"High Point Market attendance figures released", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.hickoryrecord.com/news/crowd-thins-slightly-at-nc-furniture-market-after-lgbt-law/article_0063fe40-2429-11e6-bd3a-9baf79980be0.html", "meta"=>{"publication"=>"Hickory Record", "title"=>"Crowd thins slightly at NC furniture market after LGBT law", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "High Point Market", photo_credit: "Tinxi / Shutterstock.com", tweet: "Attendance drops at North Carolina's High Point Market amidst the HB2 scandal - http://ow.ly/VUQ4304pd9W #RepealHB2 #StopHB2gether"},
  {date: "2016-04-22 04:00:00", amount: "337000.0", title: "Blue Man Group cancels North Carolina shows to protest HB2", slug: "blue-man-group", description: "The Blue Man Group cancelled it's 5 planned performances at Charlotte's Belk Theater over HB2. The group issued a statement in opposition to the discriminatory North Carolina bill.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $337,000 to the total of $350,873,000, the loss of this show is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"We value every individual’s right to live a dignified, vibrant life in full color. As such, we are joining the growing list of entertainment professionals in protest of North Carolina’s HB2 law by canceling our upcoming tour performances in Charlotte.\"\n<br><br>\n- Blue Man Group\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Blue Man Group is not only a loss for Charlotte, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.wral.com/blue-man-group-latest-group-to-cancel-show-over-hb2/15658384/", "meta"=>{"publication"=>"WRAL", "title"=>"Blue Man Group latest performers to cancel show over HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"http://wncn.com/2016/04/22/blue-man-group-cancels-charlotte-performance-citing-hb2/", "meta"=>{"publication"=>"WNCN", "title"=>"Blue Man Group cancels Charlotte performance citing HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Blue Man Group", photo_credit: "360b / Shutterstock.com", tweet: ".@bluemangroup cancels North Carolina shows in protest over the anti LGBTQ House Bill 2 - http://ow.ly/mQCf304ph76 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-15 04:00:00", amount: "9536000.0", title: "Cirque du Soleil pulls NC stops off 2016 tour, citing HB2", slug: "cirque-du-soleil", description: "Cirque du Soleil cancelled performances in Raleigh, Greensboro, and Charlotte to protest the hateful bill. In a public statement, the group emphasized it's strong belief in diversity and equality.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $9,536,000 to the total of $350,873,000, the loss of this show hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"Cirque du Soleil strongly believes in diversity and equality for every individual and is opposed to discrimination in any form. The new HB2 legislation passed in North Carolina is an important regression to ensuring human rights for all.\"\n<br><br>\n- Cirque du Soleilvia  Facebook\n <a class=\"link\" href=\"https://www.facebook.com/notes/cirque-du-soleil/cirque-du-soleil-will-not-perform-in-north-carolina/10153690474037675\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Cirque du Soleil in Raleigh, Charlotte, and and Greensboro is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"https://www.washingtonpost.com/news/post-nation/wp/2016/04/15/cirque-du-soleil-cancels-north-carolina-shows-to-protest-lgbt-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"Cirque du Soleil cancels North Carolina shows to protest LGBT law", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Elahe Izadi"}}, {"link"=>"http://www.wral.com/cirque-du-soleil-cancels-nc-shows-over-hb2/15644282/", "meta"=>{"publication"=>"WRAL", "title"=>"Cirque du Soleil latest to cancel NC shows in protest of HB2", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Arielle Clay"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Cirque du Soleil", photo_credit: "Ververidis Vasilis / Shutterstock.com", tweet: "Putting human rights before revenue, @Cirque pulls out of NC to protest HB2 - http://ow.ly/11Yi304pjG3 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-13 04:00:00", amount: "348000.0", title: "Ringo Starr cancels NC show in opposition to HB2", slug: "ringo-starr", description: "The former Beatles' drummer Ringo Starr cancelled a show in Cary, North Carolina in protest over the state's discriminatory House Bill 2. The artist made a public statement that he was 'taking a stand against this hatred'.", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $348,000 to the total of $350,873,000, the loss of this concert hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"I'm sorry to disappoint my fans in the area, but we need to take a stand against this hatred. Spread peace and love.\"\n<br><br>\n- Ringo Starr\n <a class=\"link\" href=\"http://ymlp.com/zPpUDv\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.washingtontimes.com/news/2016/apr/13/ringo-star-cancels-north-carolina-concert-protest-/", "meta"=>{"publication"=>"Washington Times", "title"=>"Ringo Starr cancels North Carolina concert in protest of transgender bathroom law", "date"=>"4/13/16", "accessed"=>"9/10/16", "author"=>"Bradford Richardson"}}, {"link"=>"http://www.newsweek.com/ringo-starr-cancels-north-carolina-concert-opposition-hb2-bill-447667", "meta"=>{"publication"=>"Newsweek", "title"=>"Ringo Starr cancels North Carolina concert in opposition to HB2 'bathroom' law", "date"=>"4/14/16", "accessed"=>"9/10/16", "author"=>"Tufayel Ahmed"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Ringo Starr", photo_credit: "Featureflash Photo Agency / Shutterstock.com", tweet: "@ringostarrmusic stands for equality and human rights, cancels NC show to protest HB2 - http://ow.ly/11Yi304pjG3 #RepealHB2 #StopHB2gether"},
  {date: "2016-09-14 04:00:00", amount: "40400000.0", title: "Citing HB2, ACC moves 10 games out of North Carolina", slug: "acc", description: "The ACC relocates all 10 championships in NC for the 2016-17 academic year out of the state in response to HB2. The ACC issued a statement affirming equality, diversity, and inclusion.", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nAccounting for nearly 12% of the total losses to the state of North Carolina to date, the  loss of this event is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"As members of the Atlantic Coast Conference, the ACC Council of Presidents reaffirmed our collective commitment to uphold the values of equality, diversity, inclusion and non-discrimination.\"\n<br><br>\n- ACC Council of Presidents\n <a class=\"link\" href=\"http://www.theacc.com/news/statements-from-the-atlantic-coast-conference-09-14-2016\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.nytimes.com/2016/09/15/sports/acc-championships-north-carolina-hb2.html", "meta"=>{"accessed"=>"9/17/16", "author"=>"Marc Tracy and Alan Binder", "date"=>"9/14/16", "publication"=>"New York Times", "title"=>"A.C.C. Pulls League Championships Out of North Carolina"}}, {"link"=>"http://www.espn.com/college-football/story/_/id/17547270/acc-moving-neutral-site-championship-games-north-carolina-due-hb2", "meta"=>{"accessed"=>"9/17/16", "author"=>"Andrea Adelson", "date"=>"9/15/16", "publication"=>"ESPN", "title"=>"ACC moving neutral-site championship games out of North Carolina due to HB2"}}, {"link"=>"https://www.wired.com/2016/09/guess-much-anti-lgbtq-law-costing-north-carolina/", "meta"=>{"accessed"=>"9/18/16", "author"=>"Emma Gray Ellis", "date"=>"9/18/16", "publication"=>"Wired", "title"=>"Guess How Much That Anti-LGBTQ Law Is Costing North Carolina"}}], active: true, featured: true, short_name: "Atlantic Coast Conference", photo_credit: "", tweet: ".@theACC stands up to discriminatory law, moving championships out of North Carolina http://ow.ly/XB7w304kjQj #RepealHB2 #StopHB2gether"},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen concert cancelled in protest of House Bill 2", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back. He was the first of many artists to cancel a performance in protest over the controversial bill.", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nThe loss of $700,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"Some things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\"\n<br><br>\n- Bruce Springsteen\n <a class=\"link\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://money.cnn.com/2016/04/08/media/bruce-springsteen-north-carolina-show-canceled/", "meta"=>{"publication"=>"CNN Money", "title"=>"Bruce Springsteen cancels North Carolina concert over 'bathroom law'", "date"=>"4/8/16", "author"=>"Tom Kludt", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "Bruce Springsteen", photo_credit: "Brian Patterson Photos / Shutterstock.com", tweet: "Doing his part to protest HB2, @springsteen cancellation results in $700,000 loss for NC http://ow.ly/Fd6x304kdvd #RepealHB2 #StopHB2gether"},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate moves move shoot out of NC because of HB2", slug: "lionsgate", description: "Santa Monica based Lionsgate studio moves production for Crushed out of Charlotte in response to HB2. The studio has moved production to Vancouver, Canada.", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nThe loss of $3,000,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"We will be hard pressed to continue our relationship with North Carolina if this regressive law remains on the books\"\n<br><br>\n- Lionsgatevia  Charlotte Observer\n <a class=\"link\" href=\"http://www.charlotteobserver.com/news/business/article69837702.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Lionsgate shoot marks yet another unnecessary loss for NC.\n", sources: [{"link"=>"http://www.fox46charlotte.com/news/local-news/116956922-story", "meta"=>{"publication"=>"Fox 46 of Charlotte", "title"=>"Lionsgate takes 100 jobs from NC due to HB2", "date"=>"4/4/16", "author"=>"Fox", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "Lionsgate", photo_credit: "Kobby Dagan / Shutterstock.com", tweet: "Lionsgate pulls production of Crushed out of NC over HB2, costing the state $3 million - http://ow.ly/9Yik304kjy7 #RepealHB2 #StopHB2gether"},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "PayPal withdraws NC investment over HB2", slug: "paypal", description: "PayPal cancels it's plans to base it's new global operations in Charlotte in protest over HB2. The company has pledged to work with the LGBTQ community in North Carolina to overturn the discriminatory law.", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing  $44,000,000 to the total of $350,873,000, the loss of this company expansion is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"The new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\"\n<br><br>\n- Dan Schulman, President and CEO of PayPal.\n <a class=\"link\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.hrc.org/blog/am-equality-tip-sheet-april-5-2016", "meta"=>{"publication"=>"Human Rights Campaign", "title"=>"#AM_Equality Tip Sheet: April 5, 2016", "date"=>"4/5/2016", "author"=>"HRC Staff", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/2016", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "PayPal", photo_credit: "Ken Wolter / Shutterstock.com", tweet: "$44 million lost for NC after PayPal withdraws investment over HB2 - http://ow.ly/3KCM304kcTo #RepealHB2 #StopHB2gether"},
  {date: "2016-04-25 04:00:00", amount: "911000.0", title: "Demi Lovato and Nick Jonas cancel NC concerts in response to HB2", slug: "demi-lovato-nick-jonas", description: "\nDemi Lovato and Nick Jonas cancelled shows in Raleigh and Charlotte in opposition to North Carolina's controversial House Bill 2. The duo said in a statement that the new law was very disappointing.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $911,000 to the total of $350,873,000, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"After much thought and deliberation, we have decided to cancel our Honda Civic Tour: Future Now shows in Raleigh and Charlotte. One of our goals for the tour has always been to create an atmosphere where every single attendee feels equal, included, and accepted for who they are.\"\n<br><br>\n- Demi Lovato and Nick Jonasvia  Twitter\n <a class=\"link\" href=\"https://twitter.com/ddlovato/status/724705165186457600\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Demi Lovato and Nick Jonas marks yet another unnecessary loss for North Carolina.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/nick-jonas-demi-lovato-cancel-north-carolina-shows-to-protest-hb2-20160425", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Nick Jonas, Demi Lovato Cancel North Carolina Shows to Protest HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article73823087.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Demi Lovato, Nick Jonas Charlotte show canceled over HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Mark Price"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Demi Lovato and Nick Jonas", photo_credit: "", tweet: ".@nickjonas and @ddlovato stand up to hate, cancelling their NC shows over HB2 - http://ow.ly/Fggc304pgW7 #RepealHB2 #StopHB2gether"},
  {date: "2016-05-17 04:00:00", amount: "74000.0", title: "Itzhak Perlman cancels NC concert in protest of HB2", slug: "itzhak-perlman", description: "Itzhak Perlman cancels his planned performance at Raleigh's Meymandi Concert Hall in protest over NC's HB2. The artist released a public statement condemning the bill, and said he looks forward to returning to the state after it's repeal.", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $74,000 to the total of $350,873,000, the loss of this concert hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"I have spent a lifetime advocating against discrimination towards those with physical disabilities and have been a vocal advocate for treating all people equally. As such, after great consideration, I have decided to cancel my May 18th concert in North Carolina with the North Carolina Symphony as a stand against House Bill 2.\"\n<br><br>\n- Itzhak Perlmanvia  Facebook\n <a class=\"link\" href=\"https://www.facebook.com/Itzhakperlmanofficial/posts/10154045664370977\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Itzhak Perlman in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.jewishjournal.com/culture/article/violinist_itzhak_perlman_scraps_n.c._concert_over_discriminatory_law", "meta"=>{"publication"=>"Jewish Journal", "title"=>"Violinist Itzhak Perlman scraps N.C. concert over ‘discriminatory’ law", "date"=>"5/17/16", "accessed"=>"9/9/16", "author"=>"Colleen Jenkins"}}, {"link"=>"http://www.npr.org/sections/deceptivecadence/2016/05/18/478556368/itzhak-perlman-on-canceling-in-north-carolina-i-had-to", "meta"=>{"publication"=>"NPR", "title"=>"Itzhak Perlman On Canceling In North Carolina: 'I Had To'", "date"=>"5/18/16", "accessed"=>"9/9/16", "author"=>"Anastasia Tsioulcas"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Itzhak Perlman", photo_credit: "Roman Yanushevsky / Shutterstock.com", tweet: "Acclaimed violinist Itzhak Perlman cancels concert in Raleigh over HB2 - http://ow.ly/8Luu304peL5 #RepealHB2 #StopHB2gether"},
  {date: "2016-09-12 04:00:00", amount: "5000000.0", title: "American Physical Society relocates 2018 conference to Florida in response to House Bill 2", slug: "american-physical-society", description: "The American Physical Society’s Division of Atomic, Molecular and Optical Physics cancelled a planned 2018 event in response to HB2. Officials with the group said they want to provide a welcoming environment for all members.", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nThe loss of $5,000,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"Although we were unhappy that withdrawing from Charlotte would punish the city whose ordinance precipitated HB2, we felt that it was imperative DAMOP and the APS provide a welcoming environment for all members.\"\n<br><br>\n- Steven Rolston, DAMOP Chair.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe American Physical Society in Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2", "accessed"=>"9/13/16"}}, {"link"=>"http://www.charlotteobserver.com/news/politics-government/article93751152.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Citing HB2, American Physical Society moves 2018 meeting from Charlotte", "date"=>"8/4/16", "accessed"=>"9/13/16", "author"=>"Steve Harrison"}}, {"link"=>"http://www.aps.org/newsroom/pressreleases/08042016.cfm", "meta"=>{"publication"=>"APS Physics", "title"=>"Discriminatory North Carolina Restroom Law Prompts Major Scientific Society to Move Annual Meeting", "date"=>"8/4/16", "accessed"=>"9/13/16", "author"=>"James Riordon"}}], active: true, featured: false, short_name: "American Physical Society", photo_credit: "", tweet: "Charlotte loses $5M after the American Physical Society cancels convention over HB2 - http://ow.ly/3JXI304klQK #RepealHB2 #StopHB2gether"},
  {date: "2016-08-23 04:00:00", amount: "8000.0", title: "Russell Wilson and Ciara moved wedding out of NC because of HB2", slug: "russell-wilson-ciara", description: "Russell Wilson and Ciara wed in London instead of North Carolina because of HB2. The couple joins a long list of celebrities and organizations who stand against HB2.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nThe loss of $8,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"They were first getting married in North Carolina, but they called it off due to the transgender bathroom laws.\"\n<br><br>\n- Mindy Weiss, Wedding planner for the couple.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://edition.cnn.com/2016/08/23/sport/russell-wilson-ciara-wedding-moved-north-carolina-transgender-bathroom-law/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Jill Martin", "date"=>"8/23/16", "publication"=>"CNN", "title"=>"Russell Wilson, Ciara moved wedding due to NC transgender law"}}, {"link"=>"http://www.newsobserver.com/news/politics-government/politics-columns-blogs/under-the-dome/article97308942.html", "meta"=>{"accessed"=>"9/17/16", "author"=>"Katherine Peralta", "date"=>"8/23/16", "publication"=>"News and Observer", "title"=>"Russell Wilson, Ciara moved their July wedding from N.C. because of HB2"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Russell Wilson and Ciara", photo_credit: "Featureflash Photo Agency / Shutterstock.com", tweet: ".@DangeRussWilson and @ciara stand up for equality, moving wedding out of NC over HB2 - http://ow.ly/9pVP304km4X #RepealHB2 #StopHB2gether"},
  {date: "2016-06-27 04:00:00", amount: "890000.0", title: "CSTE moves 2017 conference out of NC citing politics and travel bans to the state", slug: "cste", description: "The Council of State and Territorial Epidemiologists moves it's upcoming conference out of the state of NC in response to the HB2 related travel bans to the state. Raleigh city officals estimate the losses at $890,000.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nThe loss of $890,000 is another economic blow to NC over HB2.\n\n <blockquote class=\"template-quote\">\n\"While CSTE historically hosts the conference in the state of its current president, the location announcement for 2017 remains on hold, pending the repeal or amendment of North Carolina’s March 2016 House Bill 2.\"\n<br><br>\n- CSTE, group.\n <a class=\"link\" href=\"http://www.csteconference.org/2016/2017-conference-location/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Council of State and Territorial Epidemiologists is not only a loss for Raleigh, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2", "accessed"=>"9/13/16"}}, {"link"=>"http://www.csteconference.org/2016/2017-conference-location/", "meta"=>{"publication"=>"CSTE", "title"=>"2017 Conference Location", "date"=>"7/27/16", "accessed"=>"9/13/16"}}], active: true, featured: false, short_name: "Council of State and Territorial Epidemiologists", photo_credit: "", tweet: "NC loses $890,000 as CSTE moves conference over HB2 related travel bans to the state - http://ow.ly/L7YF304pcSd #RepealHB2 #StopHB2gether"},
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "The NBA moves 2017 All-Star Game out of North Carolina in response to HB2", slug: "nba-all-star-game", description: "The high profile loss of the NBA's All-Star Game is $100 million lost to NC over HB2. The NBA is moving it's 2017 game from Charlotte to New Orleans in protest of the bill.", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing a whopping $100,000,000 to the total of $350,873,000, the loss of this event hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"While we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2.\"\n<br><br>\n- NBA\n <a class=\"link\" href=\"http://www.nba.com/2016/news/07/21/nba-statement-all-star-game-relocation-from-charlotte/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe NBA All-Star Game in Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.forbes.com/sites/maurybrown/2016/07/22/the-economic-impact-of-charlotte-losing-nba-all-star-game-and-potentially-super-bowls-due-to-hb2/#6e66e6633f60", "meta"=>{"publication"=>"Forbes", "title"=>"The Economic Impact Of Charlotte Losing NBA All-Star Game, And Potentially Super Bowls Due To HB2", "date"=>"7/22/16", "author"=>"Maury Brown", "accessed"=>"9/9/16"}}, {"link"=>"https://www.washingtonpost.com/news/sports/wp/2016/07/21/report-nba-will-move-2017-all-star-game-from-charlotte-to-new-orleans-over-hb2-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"NBA will move 2017 All-Star Game from Charlotte over HB2 law", "date"=>"7/21/16", "author"=>"Tim Bontemps", "accessed"=>"9/9/16"}}, {"link"=>"http://www.espn.com/nba/story/_/id/17120170/nba-moving-all-star-game-charlotte-north-carolina-bill", "meta"=>{"publication"=>"ESPN", "author"=>"NBA", "title"=>"NBA moves 2017 All-Star Game from Charlotte over HB2 bill", "date"=>"7/22/16", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "NBA All-Star Game", photo_credit: "", tweet: "North Carolina loses $100 million after the NBA it's pulls All-Star Game over HB2 - http://ow.ly/An9X304kmBJ #RepealHB2 #StopHB2gether"},
  {date: "2016-04-25 04:00:00", amount: "950000.0", title: "American Institute of Architects moves South Atlantic Region Conference out of Wilmington because of HB2", slug: "aia", description: "The American Institute of Architects moves it's conference out of NC in response to HB2. The state of North Carolina lost an estimated $950,000 from this lost conference, adding to the list of HB2 related fallout.", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing  $950,000 to the total of $350,873,000, the loss of this conference is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"We ask lawmakers to engage in further dialogue and legislate a more equitable solution that takes into account the needs of all persons in North Carolina.\"\n<br><br>\n- AIA\n <a class=\"link\" href=\"http://www.aianc.org/government-updates/hb2-our-commitment-to-diversity-and-inclusionary-design-1\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe AIA Conference in Wilmington is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.wilmingtonbiz.com/hospitality/2016/04/26/hb2_loss_of_architect_conference_costs_wilmington_nearly_1m_estimates_show/14705", "meta"=>{"publication"=>"Wilmington Biz", "title"=>"HB2 Loss Of Architect Conference Costs Wilmington Nearly $1M, Estimates Show", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"Cece Nunn"}}, {"link"=>"http://www.aianc.org/government-updates/hb2-our-commitment-to-diversity-and-inclusionary-design-1", "meta"=>{"publication"=>"AIA NC", "title"=>"AIA South Atlantic to Move Conference From Wilmington Due to HB 2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"David Crawford"}}], active: true, featured: true, short_name: "AIA Conference", photo_credit: "", tweet: "Wilmington loses $950,000 over HB2 after @AIANational moves conference to protest bill - http://ow.ly/Tdgq304pgpq #RepealHB2 #StopHB2gether"},
  {date: "2016-04-08 04:00:00", amount: "180000.0", title: "Southern Sociological Society moves 2019 annual meeting out of Charlotte", slug: "southern-sociological-society", description: "Over $180,000 is lost to North Carolina after the Southern Sociological Society cancels it's 2019 meeting over HB2. The society states that they don't want to spend their money in a state that discriminates against members of the LGBT community.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $180,000 to the total of $350,873,000, the loss of this convention is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"We don’t want to spend our money in a state that discriminates against the L.G.B.T. community, and since our members often bring their families along to the conferences and stay in the destination for a few days after for fun, we’re talking about tourist dollars from airfare, hotel rooms and meals not going to Charlotte.\"\n<br><br>\n- Dr. Barbara Risman, former President of the Southern Sociological Society.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Southern Sociological Society is not only a loss for Charlotte, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.nytimes.com/2016/04/22/travel/north-carolina-mississippi-lgbt-gay-rights-travel.html", "meta"=>{"publication"=>"New York Times", "title"=>"North Carolina and Mississippi See Tourist Backlash After L.G.B.T. Laws", "date"=>"4/22/16", "accessed"=>"9/10/16", "author"=>"Shivani Vora"}}, {"link"=>"http://www.charlotteobserver.com/news/local/article70867152.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"13 groups drop plans for Charlotte events, more could come over HB2", "date"=>"4/8/16", "accessed"=>"9/10/16", "author"=>"David Perlmutt"}}], active: true, featured: false, short_name: "Southern Sociological Society", photo_credit: "", tweet: "Southern Sociological Society's cancels over HB2, resulting in over $180,000 lost to NC - http://ow.ly/Nhnk304pkCZ #RepealHB2 #StopHB2gether"},
  {date: "2016-04-14 04:00:00", amount: "38000.0", title: "Ani DiFranco cancels as headliner of the Eno River Festival over HB2", slug: "ani-difranco", description: "Ani DiFranco pulls out of the Eno River Festival in Durham in protest over HB2. The award winning musician released a statement condemning the discriminatory bill.", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $38,000 to the total of $350,873,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"When one of us is oppressed, all of us are oppressed, and only through the strength of our collective action will change occur.\"\n<br><br>\n- Ani DiFranco\n <a class=\"link\" href=\"http://www.indyweek.com/music/archives/2016/04/14/ani-difranco-cancels-festival-for-the-eno-appearance-citing-hb-2-and-leaving-the-eno-in-a-tight-spot\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.npr.org/sections/therecord/2016/05/06/476980045/in-north-carolina-musicians-face-off-against-hb2", "meta"=>{"accessed"=>"9/19/16", "author"=>"Jill Martin", "date"=>"5/6/16", "publication"=>"NPR", "title"=>"In North Carolina, Musicians Face Off Against HB2"}}, {"link"=>"http://www.newsobserver.com/entertainment/music-news-reviews/on-the-beat-blog/article71803442.html", "meta"=>{"accessed"=>"9/19/16", "author"=>"David Menconi", "date"=>"4/14/16", "publication"=>"News and Observer", "title"=>"Ani DiFranco cancels North Carolina"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Ani DiFranco", photo_credit: "Rachell Coe / Shutterstock.com", tweet: "Durham's Eno River Festival loses @anidifranco as a headliner over anti LGBTQ HB2  - http://ow.ly/UEbL304mUpG #RepealHB2 #StopHB2gether"},
  {date: "2016-07-24 04:00:00", amount: "3000.0", title: "UVM cancels UNC women's basketball game over HB2", slug: "uvm-vs-unc", description: "The University of Vermont women's basketball team cancels a game against the University of North Carolina in opposition to HB2. UVM athletic director says the new law is discriminatory towards the transgender community. ", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $3,000 to the total of $350,873,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"The decision to cancel to our Dec. 28 women's basketball game at North Carolina was made as a result of concerns over the HB2 law, which prevents transgender people from using government-run bathrooms based on their gender identity.\"\n<br><br>\n- Jeff Schulman, Athletic Director, UVM.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe UVM vs UNC Women's Basketball is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.burlingtonfreepress.com/story/sports/college/vermont/2016/08/24/uvm-cancels-basketball-game-unc/89303284/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Alex Abrami and Austin Danforth", "date"=>"8/24/16", "publication"=>"Burlington Free Press", "title"=>"UVM cancels basketball game at UNC over HB2 law"}}, {"link"=>"http://www.cbssports.com/college-basketball/news/womens-basketball-game-at-north-carolina-canceled-over-hb2-bathroom-bill/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Chip Patterson", "date"=>"8/25/16", "publication"=>"CBS Sports", "title"=>"Women's basketball game at North Carolina canceled over HB2 'bathroom bill'"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "University of Vermont ", photo_credit: "Debby Wong / Shutterstock.com\n", tweet: "UVM women's basketball team cancels a game against North Carolina over HB2 - http://ow.ly/JPnK304kmnm #RepealHB2 #StopHB2gether"}
])
